define("report_gradeitems/course",["jquery","core/ajax","core/notification","core/str"],function($,Ajax,Notification,Str){var state={courseid:0,activityvisibility:"",strings:{}};var loadStrings=function(){return Str.get_strings([{key:"noactivitiesfound",component:"report_gradeitems"},{key:"totalactivities_count",component:"report_gradeitems"},{key:"yes",component:"report_gradeitems"},{key:"no",component:"report_gradeitems"}]).then(function(strings){state.strings.noactivitiesfound=strings[0];state.strings.totalactivities_count=strings[1];state.strings.yes=strings[2];state.strings.no=strings[3];return true})};var fetchActivities=function(){showLoading();return Ajax.call([{methodname:"report_gradeitems_get_activities",args:{courseid:state.courseid,activityvisibility:state.activityvisibility}}])[0].then(function(response){renderTable(response);updateTotalCount(response.totalcount);hideLoading();return response}).catch(function(error){hideLoading();Notification.exception(error)})};var showLoading=function(){var tableContainer=$("#gradeitems-activities-container");tableContainer.css("opacity","0.5");if(!$("#gradeitems-loading").length){tableContainer.before('<div id="gradeitems-loading" class="text-center py-3"><div class="spinner-border text-primary" role="status"><span class="sr-only">Loading...</span></div></div>')}$("#gradeitems-loading").show()};var hideLoading=function(){$("#gradeitems-activities-container").css("opacity","1");$("#gradeitems-loading").hide()};var updateTotalCount=function(count){var text=state.strings.totalactivities_count.replace("{$a}",count);$("#gradeitems-activities-count").text(text)};var renderTable=function(response){var container=$("#gradeitems-activities-container");var tableBody=container.find("tbody");tableBody.empty();if(response.activities.length===0){container.find("table").hide();if(!$("#gradeitems-no-results").length){container.append('<div id="gradeitems-no-results" class="alert alert-info">'+state.strings.noactivitiesfound+"</div>")}$("#gradeitems-no-results").show();return}$("#gradeitems-no-results").hide();container.find("table").show();response.activities.forEach(function(activity){var row=$("<tr></tr>");row.append($("<td></td>").text(activity.section));row.append($("<td></td>").html('<a href="'+activity.activityurl+'" target="_blank">'+activity.activityname+"</a>"));row.append($("<td></td>").text(activity.moduletype));row.append($("<td></td>").text(activity.activityvisible));row.append($("<td></td>").text(activity.gradetype));row.append($("<td></td>").text(activity.grademax));row.append($("<td></td>").text(activity.gradepass));row.append($("<td></td>").text(activity.gradeweight));row.append($("<td></td>").text(activity.gradecount));row.append($("<td></td>").text(activity.gradeaverage));tableBody.append(row)})};var initEventHandlers=function(){$("#gradeitems-activityvisibility").on("change",function(){state.activityvisibility=$(this).val()||"";fetchActivities()})};var init=function(config){state.courseid=config.courseid||0;state.activityvisibility=config.activityvisibility||"";loadStrings().then(function(){initEventHandlers();return true}).catch(Notification.exception)};return{init:init}});
